import (
	"encoding/json"
	"net/http"
)

// healthResponse wraps the health check response.
type healthResponse struct {
	Data any `json:"data"`
}

// healthRoutes registers the health check endpoint.
func (s *Server) healthRoutes(mux *http.ServeMux) {
	mux.HandleFunc("GET /healthz", s.handleHealth)
}

// handleHealth responds with a 200 status and health data.
func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	usersCount := s.users.List()
	productsCount := s.products.List()
	ordersCount := s.orders.List()

	response := healthResponse{
		Data: map[string]int{
			"status":  "ok",
			"users":    usersCount,
			"products": productsCount,
			"orders":   ordersCount,
		},
	}

	writeJSON(w, http.StatusOK, response)
}

