	}
	for i, it := range req.Items {
		if it.ProductID == "" {
			return validationError{fmt.Sprintf("items[%d].product_id", i), "is required"}
		}
		if it.Quantity < 1 {
			return validationError{fmt.Sprintf("items[%d].quantity", i), "must be at least 1"}
		}
	}
	return nil
}

